use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [test] fn success_in_grandchildren () { let mut forest = ObligationForest :: new () ; forest . register_obligation ("A") ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| obligation | match * obligation { "A" => ProcessResult :: Changed (thin_vec ! ["A.1" , "A.2" , "A.3"]) , "A.1" => ProcessResult :: Changed (thin_vec ! []) , "A.2" => ProcessResult :: Changed (thin_vec ! ["A.2.i" , "A.2.ii"]) , "A.3" => ProcessResult :: Changed (thin_vec ! []) , "A.2.i" | "A.2.ii" => ProcessResult :: Unchanged , _ => unreachable ! () , } , | _ | { } ,)) ; let mut ok = ok ; ok . sort () ; assert_eq ! (ok , vec ! ["A.1" , "A.3"]) ; assert ! (err . is_empty ()) ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| obligation | match * obligation { "A.2.i" => ProcessResult :: Unchanged , "A.2.ii" => ProcessResult :: Changed (thin_vec ! []) , _ => unreachable ! () , } , | _ | { } ,)) ; assert_eq ! (ok , vec ! ["A.2.ii"]) ; assert ! (err . is_empty ()) ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| obligation | match * obligation { "A.2.i" => ProcessResult :: Changed (thin_vec ! ["A.2.i.a"]) , "A.2.i.a" => ProcessResult :: Unchanged , _ => unreachable ! () , } , | _ | { } ,)) ; assert ! (ok . is_empty ()) ; assert ! (err . is_empty ()) ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| obligation | match * obligation { "A.2.i.a" => ProcessResult :: Changed (thin_vec ! []) , _ => unreachable ! () , } , | _ | { } ,)) ; let mut ok = ok ; ok . sort () ; assert_eq ! (ok , vec ! ["A" , "A.2" , "A.2.i" , "A.2.i.a"]) ; assert ! (err . is_empty ()) ; let TestOutcome { completed : ok , errors : err , .. } = forest . process_obligations (& mut C (| _ | unreachable ! () , | _ | { })) ; assert ! (ok . is_empty ()) ; assert ! (err . is_empty ()) ; }